/**
 * Where the fire sits AROUND the number — pure geometry, no React.
 *
 * The flame used to be drawn INSIDE the digits' own box: the tongues hung in a
 * band running from 8% to 33% of the number's height and the bed of embers
 * covered its bottom 40%, so on the dashboard's Super Streak tile the fire was
 * painted across the numerals on both platforms (found capturing store
 * screenshots, 2026-10-13). A streak is a number people read: the decoration
 * cannot sit on top of it.
 *
 * So the fire now lives in two bands OUTSIDE the digits' line box — one above,
 * one below — and each band CLIPS what it draws. A tongue is deliberately
 * taller than its band (that is what makes it look like it is licking off the
 * top edge) and the clip is what guarantees that no part of it, at any point
 * of its animation, can reach a numeral.
 *
 * Everything here is a FRACTION — of the digits' box height, or of the
 * number's width — so one set of numbers holds for a 1-digit streak and for a
 * 3-digit one, for the tile's type scale and the Streaks page's, and for a
 * phone at its largest accessibility text size. There is nothing to re-tune
 * per size, which is exactly why the overlap cannot come back.
 *
 * Rendered by webapp/components/streaks/FireNumber.tsx. The native copy is
 * expo/lib/streaks/fireNumberLayout.ts (expo/components/streaks/FireNumber.tsx
 * renders it); webapp/tests/unit/fireNumber.test.tsx drives both over one
 * fixture table and fails the moment they disagree.
 */

export interface FlameTongue {
  /** Left edge, as a fraction of the number's width. */
  left: number
  /** Width, as a fraction of the number's width. */
  width: number
  /** Height, as a fraction of the digits' box height — taller than the band. */
  height: number
  /** How fast this tongue burns, in ms. */
  durationMs: number
  /** Stagger, in ms, so five tongues do not pulse as one. */
  delayMs: number
}

/** Where each tongue sits across the number, and how fast it burns. */
export const FLAME_TONGUES: readonly FlameTongue[] = [
  { left: 0.02, width: 0.11, height: 0.34, durationMs: 1050, delayMs: 0 },
  { left: 0.22, width: 0.14, height: 0.44, durationMs: 850, delayMs: 150 },
  { left: 0.44, width: 0.12, height: 0.38, durationMs: 1250, delayMs: 320 },
  { left: 0.64, width: 0.10, height: 0.30, durationMs: 950, delayMs: 480 },
  { left: 0.84, width: 0.09, height: 0.27, durationMs: 1150, delayMs: 650 },
]

/**
 * Height of the clipped band ABOVE the digits, as a fraction of their box.
 *
 * Small on purpose: on the dashboard tile the only thing above the number is
 * its own 12px label, so a taller band would trade one overlap for another.
 */
export const FLAME_BAND = 0.16

/** Height of the clipped band BELOW the digits, as a fraction of their box. */
export const EMBER_BAND = 0.2

/** How far a tongue travels up its band over one cycle, in box fractions. */
export const FLAME_RISE = 0.4

/**
 * Average advance of a numeral in the extra-bold face, in box fractions.
 * Only used to MODEL the number's width when checking the geometry — nothing
 * renders from it, both platforms measure the real text.
 */
export const DIGIT_ADVANCE = 0.62

/**
 * A fraction as a percentage string, for a CSS `left`/`width` or a React
 * Native `DimensionValue`. Rounded to 1/100 of a percent because `0.02 * 100`
 * is `2.0000000000000004` in binary floating point, and both platforms should
 * write the same clean number down.
 */
export function percent(fraction: number): string {
  return `${Math.round(fraction * 1e4) / 100}%`
}

/** A box, relative to the top-left of the digits' line box, y growing down. */
export interface Rect {
  left: number
  top: number
  width: number
  height: number
}

/** Do two boxes share any area? Touching edges do not count as overlap. */
export function rectsOverlap(a: Rect, b: Rect): boolean {
  return (
    a.left < b.left + b.width &&
    b.left < a.left + a.width &&
    a.top < b.top + b.height &&
    b.top < a.top + a.height
  )
}

/** `r` cut down to the part of it inside `clip` — zero-sized when disjoint. */
export function clipRect(r: Rect, clip: Rect): Rect {
  const left = Math.max(r.left, clip.left)
  const top = Math.max(r.top, clip.top)
  const right = Math.min(r.left + r.width, clip.left + clip.width)
  const bottom = Math.min(r.top + r.height, clip.top + clip.height)
  return { left, top, width: Math.max(0, right - left), height: Math.max(0, bottom - top) }
}

export interface FireNumberGeometry {
  /** The digits' line box — the origin of everything else. */
  digits: Rect
  /** The band above the digits. Nothing of the fire paints outside it. */
  flameBand: Rect
  /** Each tongue's own box, before the band clips it. */
  tongues: Rect[]
  /** What each tongue actually paints: its box ∩ the band. */
  paintedTongues: Rect[]
  /** The band below the digits, where the embers glow (and their blur ends). */
  emberBand: Rect
}

/**
 * The geometry for a streak of `digits` digits rendered at `boxPx` tall.
 *
 * `boxPx` is the digits' LINE BOX, not the font size: with `leading-none` (the
 * tile) they are the same, and with a looser line height the box is taller
 * than the ink, which only ever moves the bands further from a numeral.
 */
export function fireNumberGeometry({ digits, boxPx }: { digits: number; boxPx: number }): FireNumberGeometry {
  const width = Math.max(1, digits) * DIGIT_ADVANCE * boxPx
  const digitsRect: Rect = { left: 0, top: 0, width, height: boxPx }
  const flameBand: Rect = { left: 0, top: -FLAME_BAND * boxPx, width, height: FLAME_BAND * boxPx }
  const emberBand: Rect = { left: 0, top: boxPx, width, height: EMBER_BAND * boxPx }
  const tongues: Rect[] = FLAME_TONGUES.map(t => {
    const height = t.height * boxPx
    return {
      left: t.left * width,
      // Bottom-aligned in the band, so it rises out of the digits' top edge.
      top: flameBand.top + flameBand.height - height,
      width: t.width * width,
      height,
    }
  })
  return {
    digits: digitsRect,
    flameBand,
    tongues,
    paintedTongues: tongues.map(t => clipRect(t, flameBand)),
    emberBand,
  }
}
